def divide(m, r):
	if r == 1:
		if m % 2 == 0:
			return 0.0
		else:
			return 1000000000.0
	n1 = int(m / 2) + m % 2
	n2 = m - n1
	c_sum = 10 ** 9 * ((r * r) ** n1 - 1) / (r * r - 1)
	if n2 > 0:
		o_sum = 10 ** 9 * r * ((r * r) ** n2 - 1) / (r * r - 1)
	else:
		o_sum = 0
	return c_sum - o_sum
t = int(input().strip())
while t > 0:
	(m, p) = input().strip().split()
	m = int(m.strip())
	p = float(p.strip())
	chef_share = divide(m, p)
	print(chef_share, 10 ** 9 - chef_share)
	t -= 1
